DELETE FROM news;
DELETE FROM seminars;
INSERT INTO news (slug, status, date, tag, title, summary, meta_description, meta_keywords, og_image_key, body_html, related_seminar_slug) VALUES ('ai-agent-1day-open', 'published', '2026-08-15', 'セミナー', 'Claude Code AIエージェント構築1Dayセミナー、申込受付を開始しました', 'AIを「使う」から「任せる」へ。企業のAI担当者向け対面1Dayセミナー「Claude Code AIエージェント構築1Dayセミナー」（2026年9月19日・鳥取県鳥取市 SANDBOX TOTTORI）の申込受付を開始しました。', 'AIを「使う」から「任せる」へ。企業のAI担当者向け対面1Dayセミナー「Claude Code AIエージェント構築1Dayセミナー」（2026年9月19日・鳥取県鳥取市 SANDBOX TOTTORI）の申込受付を開始しました。', 'bitcraft,お知らせ,News,Claude Code,AIエージェント,セミナー,鳥取,安藤太亮', NULL, '<p>チャットに質問して終わっていませんか？<br>
Claude Codeであなた専用のAIエージェントを構築し、書類作成・データ集計・定常業務を自動化する、企業のAI担当者向け対面1Dayセミナー「Claude Code AIエージェント構築1Dayセミナー」の申込受付を開始しました。</p>

<h2>開催概要</h2>
<ul>
<li>日時：2026年9月19日（土） 10:00〜17:00</li>
<li>会場：SANDBOX TOTTORI（鳥取県鳥取市浜坂1390-224）</li>
<li>定員：10名（少人数・先着順）</li>
<li>参加費：5,500円（税込）</li>
</ul>

<p>プログラミング未経験の方でも安心してご参加いただける内容です。詳しいカリキュラムやお申込みは、セミナー詳細ページをご確認ください。</p>

<p><a href="/service/seminar/ai-agent-1day/">Claude Code AIエージェント構築1Dayセミナー 詳細ページを見る</a></p>', 'ai-agent-1day');
INSERT INTO seminars (slug, status, detail_page, event_date, event_date_display, seminar_type, title, catch_line, hero_sub, description, price_display, price_note, capacity, seats_left, hero_image_key, card_image_key, venue_summary, sections_json, google_form_url, google_form_fields_json, gas_configured, meta_description, meta_keywords) VALUES ('ai-agent-1day', 'open', 1, '2026-09-19', '2026年9月19日（土）', '1Dayセミナー', 'AIを「使う」から、AIに「任せる」へ。<br>Claude Code AIエージェント構築1Dayセミナー', 'AIを「使う」から、<br>AIに「任せる」へ。', 'チャットに質問して、終わっていませんか？<br>Claude Codeなら、あなた専用の「AIエージェント」を構築できます。<br>書類作成・データ集計・定常業務が自動で動き続ける仕組みを、<br>1日で作り上げる実践セミナー。', 'チャットに質問して終わっていませんか？Claude Codeであなた専用のAIエージェントを構築し、書類作成・データ集計・定常業務を自動化する、企業のAI担当者向け対面1Dayセミナー。', '¥5,500', '（税込）', 10, NULL, 'seminars/ai-agent-1day/hero-bg.png', 'seminars/ai-agent-1day/sns-image.png', 'SANDBOX TOTTORI（鳥取県鳥取市浜坂1390-224）', '{"target":{"title":"こんな方に届けたい","items":[{"text":"「AIを活用している」と掲げているけれど、<br>実際の業務プロセスはまだ何も変わっていない。"},{"text":"ChatGPTなどのチャットAIは使ったことがある。<br>でも、それを「仕組み」として業務に組み込めていない。"},{"text":"社内でAI活用を進めたいが、<br>何から手をつければいいか分からない。"},{"text":"属人化した業務のうち、<br>どこをAIに任せられるのか見極め方が分からない。"}]},"benefits":{"items":[{"num":"01","title":"「チャットで終わる使い方」と「業務が回る使い方」の違いが分かる","desc":"質問して終わる使い方と、成果物が自動で生まれ続ける使い方の差を、ハンズオンを通じて体感します。"},{"num":"02","title":"自社の業務を題材に、実際に動くAIエージェントを構築できる","desc":"コードは一行も書きません。それでも、今日はじめて触った方が、当日中に自社業務専用のAIエージェントを完成させます。"},{"num":"03","title":"明日から現場で使える「仕組み」を持ち帰れる","desc":"セミナー終了時点で、あなたの会社の業務に合わせた自動化の仕組みが手元にあります。明日から現場に導入できます。"},{"num":"04","title":"1ヶ月間の無料フォローアップ付き","desc":"導入後につまずいたところは、オンラインでいつでも質問可能。1ヶ月間、社内定着までを伴走します。"}]},"timeline":{"items":[{"time":"9:30〜","title":"受付開始","desc":"10:00より講義を開始いたします。受付までお越しください。"},{"time":"10:00〜12:00","title":"午前の部：AIエージェントへの「仕事の渡し方」を学ぶ","desc":"【全体の土台】AIに仕事を任せるための考え方を身につけたうえで、自社の業務を洗い出し、AIに任せる仕事を判断軸を持って見極めます。"},{"time":"12:00〜13:00","title":"昼休憩","modifier":"break"},{"time":"13:00〜16:00","title":"午後の部：自社専用のAIエージェントを構築する","desc":"書類作成・データ集計・定常業務のいずれかを題材に、実際に動くAIエージェントを組み立て、作って終わりにせず運用し続けられる仕組みに仕上げます。後半では自社の業務課題を持ち込んで、その場で解決策を完成させます。"},{"time":"16:00〜17:00","title":"交流会・ネットワーキング","desc":"参加者同士で学んだ内容や自社の課題を共有しながら交流を深めます。明日から社内に広げるためのヒントや運用ノウハウも、この時間で情報交換できます。"},{"time":"17:00","title":"終了","modifier":"end"}]},"voices":{"items":[{"text":"とても大きな学びを得ました！1日集中して学べたこと、さらに対面だったことでつまづいても手厚いサポートをしていただけたことが大きいです。全くの素人だった私がClaudeを触れていることにびっくりしています。本当にありがとうございました。","name":"","job":""},{"text":"前提知識が乏しい中でもわからないことを気軽に質問できる雰囲気だったのが大変助かりました。聞きづらい雰囲気だったら、不完全燃焼で終わっていたと思います。","name":"","job":""},{"text":"今日作ったスキルズを、明日の仕事で早速試してみようと思っています。","name":"","job":""},{"text":"講座と実践のバランスが良く、お話も非常に聞きやすく、進行も上手で楽しかったです。","name":"","job":""},{"text":"あっという間の有意義な時間でした！","name":"","job":""},{"text":"とても勉強になりました。丁寧に教えて頂きありがとうございました。","name":"","job":""}],"note":"※ 過去に開催した同シリーズセミナー（松江開催）でいただいた参加者の声です"},"speakers":{"items":[{"photoKey":"seminars/ai-agent-1day/speakers/speaker_ando.jpg","tags":["エンジニア","AIコンサルタント"],"name":"安藤 太亮","kana":"あんどう たいすけ","affil":"bitcraft 代表 / エンジニア","desc":"鳥取県立鳥取西高校出身。株式会社ゲームガムの創業に携わり、ゲーム開発支援や教育事業などを手がける。個人でも開業し、地方の生産性を高め、新しいビジネスへの挑戦ができる環境をつくることを目的に、企業内DXの支援を各社へ提供している。自らコミュニティアプリを開発・運用し、エンジニアとしての技術的な視点と、事業として成立させるための検証を重ねる視点の両方を大切にしている。現在は複数の企業でClaude環境の構築・導入を支援しており、「現場で本当に使える業務効率化」にこだわった実践的な視点から、日々の業務を変えるClaude Codeの使い方をお伝えします。"},{"photoKey":"seminars/ai-agent-1day/speakers/speaker_yoshii.png","tags":["生成AI研修講師","元IT企業役員","ファシリテーター"],"name":"吉井 秀三","kana":"よしい しゅうぞう","affil":"生成AI研修講師 / 元IT企業役員","desc":"ガイアックスの創業期から約20年在籍し、営業・事業部長・子会社社長としてM&Aや新規事業立ち上げを数多く経験。独立後は鳥取を拠点に、企業・自治体向けの生成AI研修やセミナーを数多く担当し、Google GeminiやNotebookLMなど最新の生成AIツールの実践的な活用法を検証・発信している。シニア向けの生成AI教室から子ども向けプログラミング教室まで、世代を問わない学びの場「SESSION」も運営している。当日はファシリテーターとして、参加者が自社の業務にAIエージェントを「任せる」具体的な一歩を踏み出せるようサポートします。"}]},"overview":{"rows":[{"label":"日時","valueHtml":"2026年9月19日（土） 10:00〜17:00"},{"label":"会場","valueHtml":"SANDBOX TOTTORI（鳥取県鳥取市浜坂1390-224）<br>鳥取砂丘 西側入口から徒歩1分。<br>※SANDBOX TOTTORI様のご厚意で特別に会場をご提供いただいております。恐れ入りますが、施設内カフェでの1ドリンクのご注文にご協力をお願いいたします。<br><strong>駐車場：</strong>徒歩約1分の「県営砂丘駐車場」（普通車60台）をご利用ください。<iframe src=\"https://www.google.com/maps?q=鳥取県鳥取市浜坂1390-224+SANDBOX+TOTTORI&output=embed\" class=\"sd-map-iframe\" allowfullscreen loading=\"lazy\"></iframe>"},{"label":"定員","valueHtml":"10名（少人数・先着順）<br>※ お申込み状況により、定員は変更になる場合がございます。"},{"label":"参加費","valueHtml":"5,500円（税込）<br>※事前のお振込みにてお支払いをお願いいたします。振込先はお申し込み後にお送りする確認メールにてご案内します。法人でのお申し込みなど、事前のお振込みが難しい場合は個別にご相談ください。"},{"label":"持ち物","valueHtml":"ノートPC（MacまたはWindows）、Claudeアカウント<br>※当日は <strong>Claude Code（Proプラン）</strong> を使用します。Proプランはセミナー参加費とは別途、<strong>月額 $22（約3,400円目安）</strong> のサブスクリプションをご自身でご加入いただく必要があります。申込後にお送りする事前準備ガイドに登録手順を記載します。"},{"label":"講師","valueHtml":"<a href=\"https://bitcraft.work/#about\" target=\"_blank\">安藤 太亮（あんどう たいすけ）</a><br><a href=\"https://www.instagram.com/shuzo.yoshii/\" target=\"_blank\">吉井 秀三（よしい しゅうぞう）</a>"}]},"faq":{"items":[{"question":"プログラミング経験がなくても大丈夫ですか？","answer":"はい。コードを書く必要は一切ありません。AIへの「指示の出し方」と「任せ方」を学ぶセミナーです。"},{"question":"どんな立場の方が対象ですか？","answer":"社内でAI活用を推進したい担当者・経営者・情報システム担当など、企業でAI導入を検討しているすべての方が対象です。個人事業主の方の参加も歓迎します。"},{"question":"当日使う環境は事前に準備が必要ですか？","answer":"申込後に事前準備ガイドをお送りします。Claudeアカウントの作成のみ事前にお願いしています。"},{"question":"録画や資料は後日共有されますか？","answer":"当日の資料（スライド・スクリプト）はPDFで共有します。録画配信はありません。"},{"question":"ClaudeCodeの課金体系は、APIによる従量課金ではダメですか？（Proプランは必須ですか？）","answer":"最初はSkillを構築（AIを育てる）作業を多く実施するため、多くのTokenを消費することが見込まれます。そのため、定額で使いやすいProプラン（月額$22）を使用することをお勧めしております。"},{"question":"鳥取県内在住でないと参加できませんか？","answer":"いいえ、県外からのご参加も歓迎します。現在は対面のみですが、オンライン開催のご要望が一定数集まれば検討します。<a href=\"/contact/\">お問い合わせ</a>からご連絡ください。"}]},"cta":{"closing":"「使っているのに変わらない」と感じているなら、<br>それはツールではなく、使い方の問題です。","sub":"1日の終わりに、動くAIエージェントを手に持って帰ってください。","meta":"2026年9月19日（土）10:00〜17:00　SANDBOX TOTTORI（鳥取市）<br>参加費 5,500円（税込）","btnLabel":"参加申込はこちら"}}', 'https://docs.google.com/forms/d/e/1FAIpQLScDbru2yfQwWov5n5heSOexj0-xeDSZMldRmxB8Dw7Mh9poHw/formResponse', '{"fields":[{"section":"基本情報","label":"お名前","entryId":"entry.205820999","type":"text","required":true,"placeholder":"例）山田 太郎"},{"section":"基本情報","label":"メールアドレス","entryId":"entry.2104214894","type":"email","required":true,"placeholder":"例）example@mail.com"},{"section":"基本情報","label":"電話番号","entryId":"entry.1793219310","type":"tel","placeholder":"例）090-1234-5678"},{"section":"基本情報","label":"会社名・団体名","entryId":"entry.1094658355","type":"text","placeholder":"例）株式会社〇〇"},{"section":"基本情報","label":"ご職業・ご所属","entryId":"entry.533540802","type":"radio","required":true,"otherOption":true,"options":["経営者・役員","情報システム部門","事業部門（マーケティング・営業など）","管理部門（総務・人事・経理など）","個人事業主・フリーランス"]},{"section":"AI活用状況","label":"現在AIツールをどの程度業務で活用していますか？","entryId":"entry.534106054","type":"radio","required":true,"options":["ほぼ毎日使っている","週に数回使っている","月に数回程度","ほとんど使っていない","まだ使ったことがない"]},{"section":"AI活用状況","label":"現在利用しているAIツール（複数選択可）","entryId":"entry.415787217","type":"checkbox","otherOption":true,"options":["ChatGPT","Gemini","Claude","Copilot","NotebookLM","Canva AI","Adobe Firefly","Manus","genspark","Claude Code","Cowork","ChatGPT Work","Codex","Antigravity","Gemini Spark"]},{"section":"AI活用状況","label":"AIを主にどんな用途で使っていますか？","entryId":"entry.1964328202","type":"textarea","placeholder":"例）文章の校正、アイデア出し、資料作成の下書き など"},{"section":"業務・ツール環境","label":"社内で自動化・効率化したい業務領域（複数選択可）","entryId":"entry.1572322710","type":"checkbox","otherOption":true,"options":["資料・提案書の作成","請求・経理・会計業務","問い合わせ・メール対応","データ集計・レポート作成","スケジュール・タスク管理","特に決まっていない"]},{"section":"業務・ツール環境","label":"Googleのサービスで業務利用しているもの（複数選択可）","entryId":"entry.1781068288","type":"checkbox","options":["Gmail","Google Drive","Google スプレッドシート","Google ドキュメント","Google カレンダー","Google Meet","Google Workspace（有料）","使っていない"]},{"section":"業務・ツール環境","label":"Microsoftのサービスで業務利用しているもの（複数選択可）","entryId":"entry.432587233","type":"checkbox","options":["Outlook","Excel","Word","PowerPoint","Microsoft Teams","OneDrive","Microsoft 365（有料）","使っていない"]},{"section":"業務・ツール環境","label":"その他よく使う業務ツール・サービス","entryId":"entry.918529685","type":"text","placeholder":"例）Notion、Slack、Salesforce、kintone など"},{"section":"セミナーへの期待","label":"このセミナーで最も解決したい課題・知りたいことは何ですか？","entryId":"entry.1304167824","type":"checkbox","required":true,"options":["資料・提案書作成の効率化","請求・会計業務の自動化","スケジュール・タスク管理の効率化","メール対応・文章作成の効率化","Claude Codeの基本的な使い方","自社の業務に合ったAIエージェントの構築方法","プロンプト設計・AIへの指示の出し方","社内へのAI活用推進・展開方法"]},{"section":"セミナーへの期待","label":"自動化・効率化したい具体的な業務があれば教えてください","entryId":"entry.1865271042","type":"textarea","placeholder":"例）毎月の請求書を手入力しているので自動化したい、週次レポートを自動で作りたい など"},{"section":"セミナーへの期待","label":"講師・運営への質問・事前に伝えたいことがあればご記入ください","entryId":"entry.466496510","type":"textarea","placeholder":"例）PCのOSはWindowsです、当日遅刻する可能性があります など"},{"section":"同意","label":"プライバシーポリシーに同意します。","entryId":"entry.972091842","type":"checkbox","required":true,"options":["プライバシーポリシーに同意します。"]}]}', 1, 'チャットに質問して終わっていませんか？Claude Codeであなた専用のAIエージェントを構築し、書類作成・データ集計・定常業務を自動化する、企業のAI担当者向け対面1Dayセミナー。2026年9月19日（土）開催。参加費5,500円（税込）。', 'Claude Code,AIエージェント,セミナー,AI導入,業務効率化,bitcraft,安藤太亮,吉井秀三');
INSERT INTO seminars (slug, status, detail_page, event_date, event_date_display, seminar_type, title, catch_line, hero_sub, description, price_display, price_note, capacity, seats_left, hero_image_key, card_image_key, venue_summary, sections_json, google_form_url, google_form_fields_json, gas_configured, meta_description, meta_keywords) VALUES ('claude-code-1day', 'closed', 1, '2026-06-14', '2026年6月14日（日）', '1Dayセミナー', 'AIに「仕事を渡せる人」に、今日なる。<br>Claude Code 実践1Dayセミナー', 'AIに「仕事を渡せる人」に、<br>今日なる。', 'ChatGPTに質問するだけで止まっているなら、次のステップへ。<br>Claude Codeは「道具」ではなく、あなた専用のスタッフです。<br>指示するだけで、書類・請求・定常業務が動き続ける仕組みを<br>1日で作り上げる実践セミナー。', 'ChatGPTに質問するだけで止まっているなら、次のステップへ。指示するだけで、書類・請求・定常業務が動き続ける仕組みを1日で作り上げる実践セミナー。', '¥5,000', '（税込）', 20, 3, 'seminars/claude-code-1day/hero-bg.png', 'seminars/claude-code-1day/sns-image.png', '島根県松江市', '{"target":{"title":"こんな方に届けたい","items":[{"text":"「AIを使っている」と言えるけれど、<br>毎週の提案書も、毎月の請求書も、結局自分で作っている。"},{"text":"ChatGPTで文章を直してもらったことはある。<br>でも、業務の流れそのものは何も変わっていない。"},{"text":"「もっとうまく使えれば…」と思いながら、<br>今日もタスクをこなしている。"}]},"benefits":{"items":[{"num":"01","title":"「渡せる仕事」と「自分がすべき仕事」が分かれる","desc":"毎週繰り返していた作業の8割は、実はAIに渡せます。その判断軸を、ハンズオンを通じて身体で覚えます。"},{"num":"02","title":"「動くもの」を自分で作った実感がある","desc":"コードは一行も書きません。それでも、今日初めて触った人が、当日中に自分の業務ツールを完成させます。"},{"num":"03","title":"明日から使い続けられる「仕組み」を持ち帰れる","desc":"セミナー終了時点で、あなたの実際の業務に合わせた自動化の仕組みが手元にあります。明日から本番で使えます。"},{"num":"04","title":"1ヶ月間の無料フォローアップ付き","desc":"セミナー終了後、実際の業務でつまずいたところは、Slackでいつでも質問可能。1ヶ月間、あなたの伴走者としてサポートします。"}]},"timeline":{"items":[{"time":"9:30〜","title":"受付開始","desc":"10:00より講義を開始いたします。受付までお越しください。"},{"time":"10:00〜","title":"AIへの「仕事の渡し方」を身につける","desc":"【全体の土台】ここさえ押さえれば、あとは何でも応用できます。"},{"time":"11:00〜","title":"書類仕事を丸投げする","desc":"提案書・報告書・メールをテンプレ化。<br>次回からボタン一つで生成できる形で完成させます。"},{"time":"12:00〜","title":"昼休憩","modifier":"break"},{"time":"13:00〜","title":"数字仕事を丸投げする","desc":"経費入力・請求書・集計をAIが代行。<br>毎月2〜3時間の作業を15分に圧縮します。"},{"time":"14:15〜","title":"繰り返し仕事を丸投げする","desc":"スケジュール調整・タスク整理・フォローメール。<br>「また同じ作業か」をなくします。"},{"time":"15:30〜","title":"あなた専用スタッフを育てる","desc":"自分の業務課題を持ち込んで、その場で解決策を完成。<br>AIで効率化できるタスクを見極め、AIスタッフに任せる方法を学びます。"},{"time":"16:30〜","title":"明日から使い続けるために","desc":"習慣化・アップデート対応・Q&A"},{"time":"17:00","title":"終了","modifier":"end"}]},"voices":{"items":[{"text":"「仕事の性質上、クライアントごとに依存する業務が多かったですが、それらの業務の中から効率化できそうな部分を見極め、Claude Codeを活用することで、業務の品質を維持したまま作業効率を大幅に改善することができました。」","name":"A.Tさん","job":"フリーランス デザイナー"},{"text":"「これまで、解像度の低い指示によって多くのトークンを消費してしまうことが多かったですが、的確なツール選択とプロンプトを意識することで、最小限のコストで業務改善を実現できるようになりました。」","name":"O.Tさん","job":"個人事業主 コンサルタント"}],"note":"※ 開催後に実績として掲載予定"},"speakers":{"items":[{"photoKey":"seminars/claude-code-1day/speakers/speaker_ando.jpg","tags":["バックエンドエンジニア","AIコンサルタント"],"name":"安藤 太亮","kana":"あんどう たいすけ","affil":"bitcraft 代表 / バックエンドエンジニア","desc":"バックエンドエンジニアとしての技術的素地を持ちながら、マーケティング・会社経営にも携わる実務家。現在は複数の企業でClaude環境の構築・セットアップを手がけ、AIを活用した業務改善コンサルティングを実施している。「現場で本当に使える自動化」にこだわった実践的な視点から、日々の業務を変えるClaudeCodeの使い方を伝えます。"},{"photoKey":"seminars/claude-code-1day/speakers/speaker_matsuishi.png","tags":["データサイエンス","AI研究者"],"name":"松石 将治","kana":"まついし まさはる","affil":"島根大学大学院 自然科学研究科 / データサイエンス研究","desc":"島根大学大学院自然科学研究科にてデータサイエンスを研究。AIの「なぜ動くのか」「どう考えるべきか」という理論的背景を、難解な専門用語を使わず平易に伝えることを得意とする。ClaudeCodeを使いこなすための概念・思考フレームワークを深掘りし、受講者が「なんとなく使っている」から「確信を持って使える」状態になれるよう導きます。"}]},"overview":{"rows":[{"label":"日時","valueHtml":"2026年6月14日（日） 10:00〜17:00"},{"label":"会場","valueHtml":"島根県松江市<br>※現時点ではオープンソースラボを予定しておりますが、変更になる可能性もございます。変更がある場合は、参加者へ別途ご連絡いたします。<iframe src=\"https://www.google.com/maps?q=島根県松江市&output=embed\" class=\"sd-map-iframe\" allowfullscreen loading=\"lazy\"></iframe>"},{"label":"定員","valueHtml":"20名（少人数・先着順）（当時の残席表示: 残り3名）"},{"label":"参加費","valueHtml":"5,000円（税込）<br>※当日、現地会場にてお支払いいただきます。"},{"label":"持ち物","valueHtml":"ノートPC（MacまたはWindows）、Claudeアカウント<br>※当日は <strong>Claude Code（Proプラン）</strong> を使用します。Proプランはセミナー参加費とは別途、<strong>月額 $22（約3,400円目安）</strong> のサブスクリプションをご自身でご加入いただく必要があります。申込後にお送りする事前準備ガイドに登録手順を記載します。"},{"label":"講師","valueHtml":"<a href=\"https://bitcraft.work/#about\" target=\"_blank\">安藤 太亮（あんどう たいすけ）</a><br>松石 将治（まついし まさはる）"}]},"faq":{"items":[{"question":"プログラミング経験がなくても大丈夫ですか？","answer":"はい。コードを書く必要は一切ありません。AIへの「指示の出し方」を学ぶセミナーです。"},{"question":"どんな職種の方が対象ですか？","answer":"フリーランス・個人事業主・副業中の会社員など、自分の業務効率を上げたいすべての方が対象です。"},{"question":"当日使う環境は事前に準備が必要ですか？","answer":"申込後に事前準備ガイドをお送りします。Claudeアカウントの作成のみ事前にお願いしています。"},{"question":"録画や資料は後日共有されますか？","answer":"当日の資料（スライド・スクリプト）はPDFで共有します。録画配信はありません。"},{"question":"ClaudeCodeの課金体系は、APIによる従量課金ではダメですか？（Proプランは必須ですか？）","answer":"最初はSkillを構築（AIを育てる）作業を多く実施するため、多くのTokenを消費することが見込まれます。そのため、定額で使いやすいProプラン（月額$22）を使用することをお勧めしております。"},{"question":"島根在住でないと参加できませんか？","answer":"現在は対面のみですが、オンライン開催のご要望が一定数集まれば検討します。<a href=\"/contact/\">お問い合わせ</a>からご連絡ください。"}]},"cta":{"closing":"「使っているのに変わらない」と感じているなら、<br>それはツールではなく、使い方の問題です。","sub":"1日の終わりに、動くものを手に持って帰ってください。","meta":"2026年6月14日（日）10:00〜17:00　松江市内会場<br>参加費 5,000円（税込）","btnLabel":"参加申込はこちら"}}', 'https://docs.google.com/forms/u/0/d/e/1FAIpQLScfh0RytGYaCDME32fxCtmYFTSYOK2axD46jZmSIbyeYiKM0A/formResponse', '{"fields":[{"section":"基本情報","label":"お名前","entryId":"entry.1046348761","type":"text","required":true,"placeholder":"例）山田 太郎"},{"section":"基本情報","label":"メールアドレス","entryId":"entry.711113366","type":"email","required":true,"placeholder":"例）example@mail.com"},{"section":"基本情報","label":"電話番号","entryId":"entry.2147140863","type":"tel","placeholder":"例）090-1234-5678"},{"section":"基本情報","label":"ご職業・ご所属","entryId":"entry.2125373593","type":"radio","required":true,"options":["フリーランス","個人事業主","会社員（副業あり）","会社員（副業なし）","経営者・役員","学生","その他"]},{"section":"基本情報","label":"業種・専門分野","entryId":"entry.1573105122","type":"text","placeholder":"例）Webデザイン、経理・会計、マーケティング など"},{"section":"AI活用状況","label":"現在AIツールをどの程度業務で活用していますか？","entryId":"entry.1521330138","type":"radio","required":true,"options":["ほぼ毎日使っている","週に数回使っている","月に数回程度","ほとんど使っていない","まだ使ったことがない"]},{"section":"AI活用状況","label":"現在利用しているAIツール（複数選択可）","entryId":"entry.1462533075","type":"checkbox","options":["ChatGPT","Claude（Anthropic）","Gemini（Google）","Microsoft Copilot","Perplexity","その他","使っていない"]},{"section":"AI活用状況","label":"AIを主にどんな用途で使っていますか？","entryId":"entry.1106682812","type":"textarea","placeholder":"例）文章の校正、アイデア出し、コードのエラー解決 など"},{"section":"業務・ツール環境","label":"会計・請求管理に利用しているサービス（複数選択可）","entryId":"entry.1755619368","type":"checkbox","options":["freee","マネーフォワード クラウド","弥生会計","Misoca（請求書）","Excelで手作業","特に使っていない","その他"]},{"section":"業務・ツール環境","label":"Googleのサービスで業務利用しているもの（複数選択可）","entryId":"entry.1824330249","type":"checkbox","options":["Gmail","Google Drive","Google スプレッドシート","Google ドキュメント","Google カレンダー","Google Meet","Google Workspace（有料）","使っていない"]},{"section":"業務・ツール環境","label":"Microsoftのサービスで業務利用しているもの（複数選択可）","entryId":"entry.1938327397","type":"checkbox","options":["Outlook","Excel","Word","PowerPoint","Microsoft Teams","OneDrive","Microsoft 365（有料）","使っていない"]},{"section":"業務・ツール環境","label":"その他よく使う業務ツール・サービス","entryId":"entry.1617688847","type":"text","placeholder":"例）Notion、Slack、Trello、Zoom など"},{"section":"セミナーへの期待","label":"このセミナーで最も解決したい課題・知りたいことは何ですか？","entryId":"entry.1037635033","type":"checkbox","required":true,"options":["資料・提案書作成の効率化","請求・会計業務の自動化","スケジュール・タスク管理の効率化","メール対応・文章作成の効率化","Claude Codeの基本的な使い方","自分の業務に合ったツール・仕組みの構築方法","プロンプト設計・AIへの指示の出し方"]},{"section":"セミナーへの期待","label":"自動化・効率化したい具体的な業務があれば教えてください","entryId":"entry.1387595515","type":"textarea","placeholder":"例）毎月の請求書を手入力しているので自動化したい、週次レポートを自動で作りたい など"},{"section":"セミナーへの期待","label":"講師・運営への質問・事前に伝えたいことがあればご記入ください","entryId":"entry.781250550","type":"textarea","placeholder":"例）PCのOSはWindowsです、当日遅刻する可能性があります など"},{"section":"同意","label":"プライバシーポリシーに同意します。","entryId":"entry.1015516558","type":"checkbox","required":true,"options":["プライバシーポリシーに同意します。"]}]}', 0, 'ChatGPTに質問するだけで止まっているなら、次のステップへ。指示するだけで、書類・請求・定常業務が動き続ける仕組みを1日で作り上げる実践セミナー。2026年6月14日（日）開催。参加費5,000円（税込）。', 'Claude Code,セミナー,AI,自動化,フリーランス,業務効率化,bitcraft,安藤太亮');
INSERT INTO seminars (slug, status, detail_page, event_date, event_date_display, seminar_type, title, catch_line, hero_sub, description, price_display, price_note, capacity, seats_left, hero_image_key, card_image_key, venue_summary, sections_json, google_form_url, google_form_fields_json, gas_configured, meta_description, meta_keywords) VALUES ('lp-vibe-coding-workshop', 'closed', 0, '2026-04-15', '2026年4月15日（水）', 'ワークショップ', 'バイブコーディングによる<br>爆速LP制作ワークショップ', NULL, NULL, '生成AIを活用した「バイブコーディング」手法で、デザインから実装までノーコード感覚でLPを作成する実践講座。', '¥11,000', '（税別）', 15, NULL, NULL, 'seminars/_archive/past-seminar-lp.png', NULL, '{"target":{"title":"","items":[]},"benefits":{"items":[]},"timeline":{"items":[]},"voices":{"items":[]},"speakers":{"items":[]},"overview":{"rows":[]},"faq":{"items":[]},"cta":{"closing":"","sub":"","btnLabel":""}}', NULL, NULL, 0, '生成AIを活用した「バイブコーディング」手法で、デザインから実装までノーコード感覚でLPを作成する実践講座。', NULL);
INSERT INTO seminars (slug, status, detail_page, event_date, event_date_display, seminar_type, title, catch_line, hero_sub, description, price_display, price_note, capacity, seats_left, hero_image_key, card_image_key, venue_summary, sections_json, google_form_url, google_form_fields_json, gas_configured, meta_description, meta_keywords) VALUES ('ai-education-inquiry-based-learning', 'closed', 0, '2026-03-20', '2026年3月20日（金）', '1Dayセミナー', '【教育機関向け】<br>「探究学習」×「生成AI」の新しい授業デザイン', NULL, NULL, '生徒の「問い」を深める生成AIの効果的な活用方法と、探究学習を加速させるプロンプト設計を学ぶ教育者向けセミナー。', '¥12,000', '（税別）', 30, NULL, NULL, 'seminars/_archive/past-seminar-edu.png', NULL, '{"target":{"title":"","items":[]},"benefits":{"items":[]},"timeline":{"items":[]},"voices":{"items":[]},"speakers":{"items":[]},"overview":{"rows":[]},"faq":{"items":[]},"cta":{"closing":"","sub":"","btnLabel":""}}', NULL, NULL, 0, '生徒の「問い」を深める生成AIの効果的な活用方法と、探究学習を加速させるプロンプト設計を学ぶ教育者向けセミナー。', NULL);
INSERT INTO seminars (slug, status, detail_page, event_date, event_date_display, seminar_type, title, catch_line, hero_sub, description, price_display, price_note, capacity, seats_left, hero_image_key, card_image_key, venue_summary, sections_json, google_form_url, google_form_fields_json, gas_configured, meta_description, meta_keywords) VALUES ('ai-ops-automation-course', 'closed', 0, '2026-02-20', '2026年2月20日（金）', 'オンライン講座', 'システム保守運用の<br>AI完全自動化 実践講座', NULL, NULL, 'システムの保守運用をAIで効率化。ユーザーからのFBを元に、Issueの発案からPRの作成、コードレビューまで全て自動化する手法を学びます。', '¥18,000', '（税別）', 50, NULL, NULL, 'seminars/_archive/past-seminar-ai-ops.png', NULL, '{"target":{"title":"","items":[]},"benefits":{"items":[]},"timeline":{"items":[]},"voices":{"items":[]},"speakers":{"items":[]},"overview":{"rows":[]},"faq":{"items":[]},"cta":{"closing":"","sub":"","btnLabel":""}}', NULL, NULL, 0, 'システムの保守運用をAIで効率化。ユーザーからのFBを元に、Issueの発案からPRの作成、コードレビューまで全て自動化する手法を学びます。', NULL);
